const paper = $json;

const authors = Array.isArray(paper.authors)
  ? paper.authors.map(author => author.name).join(', ')
  : '';

return {
  json: {
    title: paper.title,
    abstract: paper.abstract,
    authors: authors,
    published: paper.published,
    updated: paper.updated,
    id: paper.id,
    url: paper.url
  }
};

const items = $input.all();

function cleanText(text) {
  if (!text) {
    return "Not specified";
  }

  let value = String(text);

  value = value.replace(/\*\*/g, "");
  value = value.replace(/^#+\s*/gm, "");
  value = value.replace(/^\s*[-•]\s*/gm, "");
  value = value.replace(/^\s*['"`]+/gm, "");
  value = value.replace(/[ \t]+/g, " ");
  value = value.replace(/\n\s*\n+/g, "\n");

  return value.trim() || "Not specified";
}

return items.map(item => {
  const data = item.json;

  let analysis = "";

  if (
    data.choices &&
    data.choices[0] &&
    data.choices[0].message &&
    data.choices[0].message.content
  ) {
    analysis = data.choices[0].message.content;
  }

  return {
    json: {
      analysis: cleanText(analysis)
    }
  };
});

const analysisItems = $input.all();
const paperItems = $('Clean Paper Data').all();

return analysisItems.map((item, index) => {
  const analysis = item.json.analysis || "";
  const paper = paperItems[index]?.json || {};

  const keyFindings =
    analysis.match(/KEY FINDINGS:\s*([\s\S]*?)(?=\nMETHODS USED:|$)/i)?.[1]?.trim() || "Not specified";

  const methods =
    analysis.match(/METHODS USED:\s*([\s\S]*?)(?=\nDATASETS:|$)/i)?.[1]?.trim() || "Not specified";

  const datasets =
    analysis.match(/DATASETS:\s*([\s\S]*?)(?=\nRESEARCH GAPS:|$)/i)?.[1]?.trim() || "Not specified";

  const researchGaps =
    analysis.match(/RESEARCH GAPS:\s*([\s\S]*?)(?=\nSUMMARY:|$)/i)?.[1]?.trim() || "Not specified";

  const summary =
    analysis.match(/SUMMARY:\s*([\s\S]*?)$/i)?.[1]?.trim() || "Not specified";

  return {
    json: {
      title: paper.title || "Not specified",
      authors: paper.authors || "Not specified",
      published: paper.published || "Not specified",
      updated: paper.updated || "Not specified",
      id: paper.id || "Not specified",
      url: paper.url || "Not specified",

      key_findings: keyFindings,
      methods_used: methods,
      datasets: datasets,
      research_gaps: researchGaps,
      summary: summary
    }
  };
});

const items = $input.all();

function cleanText(value) {
  if (value === null || value === undefined) {
    return "Not specified";
  }

  let text = String(value).trim();

  if (!text) {
    return "Not specified";
  }

  // Prevent Excel from treating text as a formula
  if (/^[=+\-@]/.test(text)) {
    text = "'" + text;
  }

  return text;
}

return items.map(item => {
  const url = item.json.url;

  let paperUrl = "Not specified";

  if (Array.isArray(url)) {
    const htmlUrl = url.find(x => x?.type === "text/html");
    paperUrl = htmlUrl?.href || url[0]?.href || "Not specified";
  } else if (typeof url === "string") {
    paperUrl = url;
  }

  return {
    json: {
      title: cleanText(item.json.title),
      authors: cleanText(item.json.authors),
      published: cleanText(item.json.published),
      updated: cleanText(item.json.updated),
      id: cleanText(item.json.id),
      url: cleanText(paperUrl),

      key_findings: cleanText(item.json.key_findings),
      methods_used: cleanText(item.json.methods_used),
      datasets: cleanText(item.json.datasets),
      research_gaps: cleanText(item.json.research_gaps),
      summary: cleanText(item.json.summary)
    }
  };
});

