const items = $input.all();

return items.map(item => {
  const data = item.json;

  let text = "";

  // Model ke different possible output locations check karo
  if (data.choices?.[0]?.message?.content) {
    text = data.choices[0].message.content;
  } 
  else if (data.reasoning?.text) {
    text = data.reasoning.text;
  }
  else if (data.svgtext) {
    text = data.svgtext;
  }

  // Markdown JSON fences remove karo
  text = String(text)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  // JSON object find karo
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");

  if (start !== -1 && end !== -1) {
    text = text.substring(start, end + 1);
  }

  let comparison;

  try {
    comparison = JSON.parse(text);
  } catch (error) {
    comparison = {
      common_findings: "Not specified",
      methods_comparison: "Not specified",
      dataset_comparison: "Not specified",
      key_differences: "Not specified",
      common_limitations: "Not specified",
      research_trends: "Not specified",
      overall_comparison_summary: text || "Not specified"
    };
  }

  return {
    json: comparison
  };
});

