return papers.map((paper, index) => {

  const links = Array.isArray(paper.link)
    ? paper.link
    : [paper.link];

  const htmlLink = links.find(
    link => link?.href && link?.type === "text/html"
  );

  const authors = Array.isArray(paper.author)
    ? paper.author
        .map(author => author?.name)
        .filter(Boolean)
        .join(", ")
    : "Not specified";

  return {
    json: {
      paper_number: index + 1,
      title: paper.title || "Not specified",
      authors: authors,
      published: paper.published || "Not specified",
      updated: paper.updated || "Not specified",
      id: paper.id || "Not specified",
      url: htmlLink?.href || "Not specified",
      summary: paper.summary || "Not specified"
    }
  };
});

const now = new Date();
const sevenDaysAgo = new Date(now);
sevenDaysAgo.setDate(now.getDate() - 7);

const items = $input.all();

return items.filter(item => {
  const published = item.json.svgpublished || item.json.published;

  if (!published) {
    return false;
  }

  const publishedDate = new Date(published);

  return publishedDate >= sevenDaysAgo && publishedDate <= now;
});

